package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_Simple() {
        byte[] buffer = "0000123".getBytes();
        assertEquals(9L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithLeadingZerosAndSpaces() {
        // Testing the 'stillPadding' logic and space skipping
        byte[] buffer = "  000755".getBytes();
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithNullTerminator() {
        // Testing the 'if (currentByte == 0) break;' branch
        byte[] buffer = "0123\0456".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithTrailingSpaceAfterPadding() {
        // Testing the 'if (currentByte == (byte) ' ') break;' inside the padding check
        // This occurs if a space is encountered after the first non-zero/non-space digit is processed
        // Wait, the logic says: if (stillPadding) continue; if (currentByte == ' ') break;
        // To hit the break, stillPadding must be false.
        byte[] buffer = "00012 34".getBytes();
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_OffsetAndLength() {
        byte[] buffer = "abc00077def";
        // Start at index 3, length 5 -> "00077"
        assertEquals(63L, TarUtils.parseOctal(buffer, 3, 5));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        // Testing the 'currentByte < '0' || currentByte > '7'' branch
        byte[] buffer = "0008".getBytes();
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharInMiddle() {
        byte[] buffer = "0001A3".getBytes();
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test
    public void testParseOctal_EmptyBuffer() {
        byte[] buffer = new byte[0];
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 0));
    }

    @Test
    public void testParseOctal_OnlyPadding() {
        byte[] buffer = "  000  ".getBytes();
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_MaxLongValue() {
        // Testing large octal values
        byte[] buffer = "777777777777777".getBytes();
        long expected = Long.parseLong("777777777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, buffer.length));
    }
}
